    chraProblemTitle: { en:"Do You Need a CHRA?", ms:"Do You Need a CHRA?", zh:"Do You Need a CHRA?", ta:"Do You Need a CHRA?" },
    chraProblemText: { en:"Malaysian workplaces handling scheduled chemicals — including solvents, acids, heavy metals, and toxic gases — must conduct a Chemical Health Risk Assessment (CHRA) under the USECHH Regulations 2000. Many facilities have never completed a proper CHRA, or their assessment is outdated and will not survive a DOSH inspection.", ms:"Malaysian workplaces handling scheduled chemicals — including solvents, acids, heavy metals, and toxic gases — must conduct a Chemical Health Risk Assessment (CHRA) under the USECHH Regulations 2000. Many facilities have never completed a proper CHRA, or their assessment is outdated and will not survive a DOSH inspection.", zh:"Malaysian workplaces handling scheduled chemicals — including solvents, acids, heavy metals, and toxic gases — must conduct a Chemical Health Risk Assessment (CHRA) under the USECHH Regulations 2000. Many facilities have never completed a proper CHRA, or their assessment is outdated and will not survive a DOSH inspection.", ta:"Malaysian workplaces handling scheduled chemicals — including solvents, acids, heavy metals, and toxic gases — must conduct a Chemical Health Risk Assessment (CHRA) under the USECHH Regulations 2000. Many facilities have never completed a proper CHRA, or their assessment is outdated and will not survive a DOSH inspection." },
    chraStakesTitle: { en:"The Stakes", ms:"The Stakes", zh:"The Stakes", ta:"The Stakes" },
    chraStakesH1: { en:"USECHH Non-Compliance Penalties", ms:"USECHH Non-Compliance Penalties", zh:"USECHH Non-Compliance Penalties", ta:"USECHH Non-Compliance Penalties" },
    chraStakesP1: { en:"Non-compliance with USECHH 2000 carries penalties under the OSH Act. DOSH inspectors now specifically request CHRA documentation during scheduled and surprise inspections.", ms:"Non-compliance with USECHH 2000 carries penalties under the OSH Act. DOSH inspectors now specifically request CHRA documentation during scheduled and surprise inspections.", zh:"Non-compliance with USECHH 2000 carries penalties under the OSH Act. DOSH inspectors now specifically request CHRA documentation during scheduled and surprise inspections.", ta:"Non-compliance with USECHH 2000 carries penalties under the OSH Act. DOSH inspectors now specifically request CHRA documentation during scheduled and surprise inspections." },
