    chraStakesP3: { en:"Insurance underwriters increasingly require current CHRA reports for renewal. Tender submissions for government contracts often mandate USECHH compliance proof.", ms:"Insurance underwriters increasingly require current CHRA reports for renewal. Tender submissions for government contracts often mandate USECHH compliance proof.", zh:"Insurance underwriters increasingly require current CHRA reports for renewal. Tender submissions for government contracts often mandate USECHH compliance proof.", ta:"Insurance underwriters increasingly require current CHRA reports for renewal. Tender submissions for government contracts often mandate USECHH compliance proof." },
