    chraFaqTitle: { en:"Frequently Asked Questions", ms:"Frequently Asked Questions", zh:"Frequently Asked Questions", ta:"Frequently Asked Questions" },
    chraFaq1Q: { en:"How often must a CHRA be conducted?", ms:"How often must a CHRA be conducted?", zh:"How often must a CHRA be conducted?", ta:"How often must a CHRA be conducted?" },
    chraFaq1A: { en:"DOSH recommends reviewing your CHRA whenever there is a significant change in chemical usage, process, or workplace layout. High-risk facilities should conduct annual reviews.", ms:"DOSH recommends reviewing your CHRA whenever there is a significant change in chemical usage, process, or workplace layout. High-risk facilities should conduct annual reviews.", zh:"DOSH recommends reviewing your CHRA whenever there is a significant change in chemical usage, process, or workplace layout. High-risk facilities should conduct annual reviews.", ta:"DOSH recommends reviewing your CHRA whenever there is a significant change in chemical usage, process, or workplace layout. High-risk facilities should conduct annual reviews." },
    chraFaq2Q: { en:"What is the difference between CHRA and HIRARC?", ms:"What is the difference between CHRA and HIRARC?", zh:"What is the difference between CHRA and HIRARC?", ta:"What is the difference between CHRA and HIRARC?" },
    chraFaq2A: { en:"HIRARC covers all workplace hazards broadly. CHRA is specific to chemical health risks under USECHH 2000 and requires exposure monitoring data. Most chemical facilities need both.", ms:"HIRARC covers all workplace hazards broadly. CHRA is specific to chemical health risks under USECHH 2000 and requires exposure monitoring data. Most chemical facilities need both.", zh:"HIRARC covers all workplace hazards broadly. CHRA is specific to chemical health risks under USECHH 2000 and requires exposure monitoring data. Most chemical facilities need both.", ta:"HIRARC covers all workplace hazards broadly. CHRA is specific to chemical health risks under USECHH 2000 and requires exposure monitoring data. Most chemical facilities need both." },
    chraFaq3Q: { en:"Do we need to stop production during monitoring?", ms:"Do we need to stop production during monitoring?", zh:"Do we need to stop production during monitoring?", ta:"Do we need to stop production during monitoring?" },
    chraFaq3A: { en:"No. We conduct exposure monitoring during normal operations to capture real-world exposure levels. Workers should not modify their behaviour during sampling.", ms:"No. We conduct exposure monitoring during normal operations to capture real-world exposure levels. Workers should not modify their behaviour during sampling.", zh:"No. We conduct exposure monitoring during normal operations to capture real-world exposure levels. Workers should not modify their behaviour during sampling.", ta:"No. We conduct exposure monitoring during normal operations to capture real-world exposure levels. Workers should not modify their behaviour during sampling." },
    chraFaq4Q: { en:"How long does the assessment take?", ms:"How long does the assessment take?", zh:"How long does the assessment take?", ta:"How long does the assessment take?" },
    chraFaq4A: { en:"Typically 3–5 working days on site for monitoring, plus 7–10 working days for laboratory analysis and report preparation.", ms:"Typically 3–5 working days on site for monitoring, plus 7–10 working days for laboratory analysis and report preparation.", zh:"Typically 3–5 working days on site for monitoring, plus 7–10 working days for laboratory analysis and report preparation.", ta:"Typically 3–5 working days on site for monitoring, plus 7–10 working days for laboratory analysis and report preparation." },
    chraFaq5Q: { en:"Can you help us upgrade our LEV system?", ms:"Can you help us upgrade our LEV system?", zh:"Can you help us upgrade our LEV system?", ta:"Can you help us upgrade our LEV system?" },
    chraFaq5A: { en:"Yes. Our LEV inspection and upgrade recommendations are integrated into the CHRA process. We verify capture velocity, airflow rates, and system integrity.", ms:"Yes. Our LEV inspection and upgrade recommendations are integrated into the CHRA process. We verify capture velocity, airflow rates, and system integrity.", zh:"Yes. Our LEV inspection and upgrade recommendations are integrated into the CHRA process. We verify capture velocity, airflow rates, and system integrity.", ta:"Yes. Our LEV inspection and upgrade recommendations are integrated into the CHRA process. We verify capture velocity, airflow rates, and system integrity." },
    chraFaq6Q: { en:"Is CHRA required for small workshops?", ms:"Is CHRA required for small workshops?", zh:"Is CHRA required for small workshops?", ta:"Is CHRA required for small workshops?" },
    chraFaq6A: { en:"If you use any scheduled chemical under USECHH 2000 — regardless of facility size — a CHRA is mandatory.", ms:"If you use any scheduled chemical under USECHH 2000 — regardless of facility size — a CHRA is mandatory.", zh:"If you use any scheduled chemical under USECHH 2000 — regardless of facility size — a CHRA is mandatory.", ta:"If you use any scheduled chemical under USECHH 2000 — regardless of facility size — a CHRA is mandatory." },
