    cidbFaqTitle: { en:"Frequently Asked Questions", ms:"Frequently Asked Questions", zh:"Frequently Asked Questions", ta:"Frequently Asked Questions" },
    cidbFaq1Q: { en:"How long is the Green Card valid?", ms:"How long is the Green Card valid?", zh:"How long is the Green Card valid?", ta:"How long is the Green Card valid?" },
    cidbFaq1A: { en:"CIDB Green Cards are typically valid for 3 years. Renewal requires re-assessment. We track expiry dates and remind you 60 days in advance.", ms:"CIDB Green Cards are typically valid for 3 years. Renewal requires re-assessment. We track expiry dates and remind you 60 days in advance.", zh:"CIDB Green Cards are typically valid for 3 years. Renewal requires re-assessment. We track expiry dates and remind you 60 days in advance.", ta:"CIDB Green Cards are typically valid for 3 years. Renewal requires re-assessment. We track expiry dates and remind you 60 days in advance." },
    cidbFaq2Q: { en:"Can foreign workers get a Green Card?", ms:"Can foreign workers get a Green Card?", zh:"Can foreign workers get a Green Card?", ta:"Can foreign workers get a Green Card?" },
    cidbFaq2A: { en:"Yes. Foreign workers legally employed on Malaysian construction sites must hold a valid SICW. We process registration for both local and foreign workers.", ms:"Yes. Foreign workers legally employed on Malaysian construction sites must hold a valid SICW. We process registration for both local and foreign workers.", zh:"Yes. Foreign workers legally employed on Malaysian construction sites must hold a valid SICW. We process registration for both local and foreign workers.", ta:"Yes. Foreign workers legally employed on Malaysian construction sites must hold a valid SICW. We process registration for both local and foreign workers." },
    cidbFaq3Q: { en:"Do supervisors and engineers need Green Cards too?", ms:"Do supervisors and engineers need Green Cards too?", zh:"Do supervisors and engineers need Green Cards too?", ta:"Do supervisors and engineers need Green Cards too?" },
    cidbFaq3A: { en:"Yes. Every individual physically present on an active construction site must hold a valid SICW, including project managers, engineers, and visitors on extended stays.", ms:"Yes. Every individual physically present on an active construction site must hold a valid SICW, including project managers, engineers, and visitors on extended stays.", zh:"Yes. Every individual physically present on an active construction site must hold a valid SICW, including project managers, engineers, and visitors on extended stays.", ta:"Yes. Every individual physically present on an active construction site must hold a valid SICW, including project managers, engineers, and visitors on extended stays." },
    cidbFaq4Q: { en:"What happens if CIDB inspects and finds uncertified workers?", ms:"What happens if CIDB inspects and finds uncertified workers?", zh:"What happens if CIDB inspects and finds uncertified workers?", ta:"What happens if CIDB inspects and finds uncertified workers?" },
    cidbFaq4A: { en:"Workers may be barred from site. Repeated violations can lead to project suspension and downgrade of your CIDB contractor registration. We provide same-day emergency batch training for inspection-triggered compliance gaps.", ms:"Workers may be barred from site. Repeated violations can lead to project suspension and downgrade of your CIDB contractor registration. We provide same-day emergency batch training for inspection-triggered compliance gaps.", zh:"Workers may be barred from site. Repeated violations can lead to project suspension and downgrade of your CIDB contractor registration. We provide same-day emergency batch training for inspection-triggered compliance gaps.", ta:"Workers may be barred from site. Repeated violations can lead to project suspension and downgrade of your CIDB contractor registration. We provide same-day emergency batch training for inspection-triggered compliance gaps." },
    cidbFaq5Q: { en:"Is SICW training HRD Corp claimable?", ms:"Is SICW training HRD Corp claimable?", zh:"Is SICW training HRD Corp claimable?", ta:"Is SICW training HRD Corp claimable?" },
    cidbFaq5A: { en:"Yes, when delivered by our HRD Corp-certified trainers. We assist with e-TRiS documentation for batch training claims.", ms:"Yes, when delivered by our HRD Corp-certified trainers. We assist with e-TRiS documentation for batch training claims.", zh:"Yes, when delivered by our HRD Corp-certified trainers. We assist with e-TRiS documentation for batch training claims.", ta:"Yes, when delivered by our HRD Corp-certified trainers. We assist with e-TRiS documentation for batch training claims." },
    cidbFaq6Q: { en:"Can you train on our construction site?", ms:"Can you train on our construction site?", zh:"Can you train on our construction site?", ta:"Can you train on our construction site?" },
    cidbFaq6A: { en:"Absolutely. We deliver SICW training directly on your site, minimising worker downtime and transport costs. All equipment and materials provided.", ms:"Absolutely. We deliver SICW training directly on your site, minimising worker downtime and transport costs. All equipment and materials provided.", zh:"Absolutely. We deliver SICW training directly on your site, minimising worker downtime and transport costs. All equipment and materials provided.", ta:"Absolutely. We deliver SICW training directly on your site, minimising worker downtime and transport costs. All equipment and materials provided." },
