    hirarcHeroSubtitle: { en:"Hazard Identification, Risk Assessment and Risk Control. Required for every Malaysian workplace with 5 or more workers under the OSH Act 1994.", ms:"Hazard Identification, Risk Assessment and Risk Control. Required for every Malaysian workplace with 5 or more workers under the OSH Act 1994.", zh:"Hazard Identification, Risk Assessment and Risk Control. Required for every Malaysian workplace with 5 or more workers under the OSH Act 1994.", ta:"Hazard Identification, Risk Assessment and Risk Control. Required for every Malaysian workplace with 5 or more workers under the OSH Act 1994." },
    hirarcHeroBtnWa: { en:"WhatsApp for HIRARC Assessment", ms:"WhatsApp for HIRARC Assessment", zh:"WhatsApp for HIRARC Assessment", ta:"WhatsApp for HIRARC Assessment" },
    hirarcHeroBtnContact: { en:"Request Assessment Proposal", ms:"Request Assessment Proposal", zh:"Request Assessment Proposal", ta:"Request Assessment Proposal" },
    hirarcProblemTitle: { en:"Do You Need a HIRARC?", ms:"Do You Need a HIRARC?", zh:"Do You Need a HIRARC?", ta:"Do You Need a HIRARC?" },
    hirarcProblemText: { en:"Under the OSH Act 1994, every employer must conduct a systematic Hazard Identification, Risk Assessment and Risk Control (HIRARC) for their workplace. Yet many Malaysian SMEs have either never completed one, or their HIRARC is a generic template downloaded from the internet that does not reflect actual site hazards.", ms:"Under the OSH Act 1994, every employer must conduct a systematic Hazard Identification, Risk Assessment and Risk Control (HIRARC) for their workplace. Yet many Malaysian SMEs have either never completed one, or their HIRARC is a generic template downloaded from the internet that does not reflect actual site hazards.", zh:"Under the OSH Act 1994, every employer must conduct a systematic Hazard Identification, Risk Assessment and Risk Control (HIRARC) for their workplace. Yet many Malaysian SMEs have either never completed one, or their HIRARC is a generic template downloaded from the internet that does not reflect actual site hazards.", ta:"Under the OSH Act 1994, every employer must conduct a systematic Hazard Identification, Risk Assessment and Risk Control (HIRARC) for their workplace. Yet many Malaysian SMEs have either never completed one, or their HIRARC is a generic template downloaded from the internet that does not reflect actual site hazards." },
    hirarcStakesTitle: { en:"The Stakes", ms:"The Stakes", zh:"The Stakes", ta:"The Stakes" },
    hirarcStakesH1: { en:"DOSH Audit Failure", ms:"DOSH Audit Failure", zh:"DOSH Audit Failure", ta:"DOSH Audit Failure" },
    hirarcStakesP1: { en:"DOSH inspectors specifically request the HIRARC register during compliance audits. An outdated or generic HIRARC is treated as non-compliance. Employers face fines and stop-work orders.", ms:"DOSH inspectors specifically request the HIRARC register during compliance audits. An outdated or generic HIRARC is treated as non-compliance. Employers face fines and stop-work orders.", zh:"DOSH inspectors specifically request the HIRARC register during compliance audits. An outdated or generic HIRARC is treated as non-compliance. Employers face fines and stop-work orders.", ta:"DOSH inspectors specifically request the HIRARC register during compliance audits. An outdated or generic HIRARC is treated as non-compliance. Employers face fines and stop-work orders." },
    hirarcStakesH2: { en:"Civil Litigation Evidence", ms:"Civil Litigation Evidence", zh:"Civil Litigation Evidence", ta:"Civil Litigation Evidence" },
    hirarcStakesP2: { en:"In the event of an accident, an inadequate HIRARC can be used as evidence of negligence in civil litigation. A robust, site-specific register is your best defence.", ms:"In the event of an accident, an inadequate HIRARC can be used as evidence of negligence in civil litigation. A robust, site-specific register is your best defence.", zh:"In the event of an accident, an inadequate HIRARC can be used as evidence of negligence in civil litigation. A robust, site-specific register is your best defence.", ta:"In the event of an accident, an inadequate HIRARC can be used as evidence of negligence in civil litigation. A robust, site-specific register is your best defence." },
    hirarcStakesH3: { en:"Insurance Premium Impact", ms:"Insurance Premium Impact", zh:"Insurance Premium Impact", ta:"Insurance Premium Impact" },
    hirarcStakesP3: { en:"Insurance underwriters increasingly review HIRARC documentation when setting premiums. A current, well-maintained register signals proactive risk management and can reduce rates.", ms:"Insurance underwriters increasingly review HIRARC documentation when setting premiums. A current, well-maintained register signals proactive risk management and can reduce rates.", zh:"Insurance underwriters increasingly review HIRARC documentation when setting premiums. A current, well-maintained register signals proactive risk management and can reduce rates.", ta:"Insurance underwriters increasingly review HIRARC documentation when setting premiums. A current, well-maintained register signals proactive risk management and can reduce rates." },
