    hirarcDetection6: { en:"A recent near-miss revealed a hazard not listed in your current register", ms:"A recent near-miss revealed a hazard not listed in your current register", zh:"A recent near-miss revealed a hazard not listed in your current register", ta:"A recent near-miss revealed a hazard not listed in your current register" },
