    hirarcFaq1Q: { en:"What is the difference between HIRARC and CHRA?", ms:"What is the difference between HIRARC and CHRA?", zh:"What is the difference between HIRARC and CHRA?", ta:"What is the difference between HIRARC and CHRA?" },
    hirarcFaq1A: { en:"HIRARC is a broad hazard assessment covering all workplace risks. CHRA is specific to chemical health risks under USECHH 2000. Most industrial workplaces need both.", ms:"HIRARC is a broad hazard assessment covering all workplace risks. CHRA is specific to chemical health risks under USECHH 2000. Most industrial workplaces need both.", zh:"HIRARC is a broad hazard assessment covering all workplace risks. CHRA is specific to chemical health risks under USECHH 2000. Most industrial workplaces need both.", ta:"HIRARC is a broad hazard assessment covering all workplace risks. CHRA is specific to chemical health risks under USECHH 2000. Most industrial workplaces need both." },
    hirarcFaq2Q: { en:"How often must HIRARC be updated?", ms:"How often must HIRARC be updated?", zh:"How often must HIRARC be updated?", ta:"How often must HIRARC be updated?" },
    hirarcFaq2A: { en:"DOSH recommends reviewing your HIRARC at least annually, and immediately after any significant change in processes, machinery, or chemicals. We schedule automatic annual reviews for our clients.", ms:"DOSH recommends reviewing your HIRARC at least annually, and immediately after any significant change in processes, machinery, or chemicals. We schedule automatic annual reviews for our clients.", zh:"DOSH recommends reviewing your HIRARC at least annually, and immediately after any significant change in processes, machinery, or chemicals. We schedule automatic annual reviews for our clients.", ta:"DOSH recommends reviewing your HIRARC at least annually, and immediately after any significant change in processes, machinery, or chemicals. We schedule automatic annual reviews for our clients." },
    hirarcFaq3Q: { en:"Can we use software to manage HIRARC?", ms:"Can we use software to manage HIRARC?", zh:"Can we use software to manage HIRARC?", ta:"Can we use software to manage HIRARC?" },
    hirarcFaq3A: { en:"Yes. We provide digital HIRARC registers with automatic reminder triggers, photo evidence uploads, and real-time risk score updates. Compatible with most EHS management platforms.", ms:"Yes. We provide digital HIRARC registers with automatic reminder triggers, photo evidence uploads, and real-time risk score updates. Compatible with most EHS management platforms.", zh:"Yes. We provide digital HIRARC registers with automatic reminder triggers, photo evidence uploads, and real-time risk score updates. Compatible with most EHS management platforms.", ta:"Yes. We provide digital HIRARC registers with automatic reminder triggers, photo evidence uploads, and real-time risk score updates. Compatible with most EHS management platforms." },
    hirarcFaq4Q: { en:"How long does a HIRARC assessment take?", ms:"How long does a HIRARC assessment take?", zh:"How long does a HIRARC assessment take?", ta:"How long does a HIRARC assessment take?" },
    hirarcFaq4A: { en:"A typical SME facility requires 1–2 days on site for walkthrough and data collection, plus 5–7 working days for report preparation. Large industrial complexes may require 3–5 days.", ms:"A typical SME facility requires 1–2 days on site for walkthrough and data collection, plus 5–7 working days for report preparation. Large industrial complexes may require 3–5 days.", zh:"A typical SME facility requires 1–2 days on site for walkthrough and data collection, plus 5–7 working days for report preparation. Large industrial complexes may require 3–5 days.", ta:"A typical SME facility requires 1–2 days on site for walkthrough and data collection, plus 5–7 working days for report preparation. Large industrial complexes may require 3–5 days." },
    hirarcFaq5Q: { en:"Do you train our staff to maintain the HIRARC?", ms:"Do you train our staff to maintain the HIRARC?", zh:"Do you train our staff to maintain the HIRARC?", ta:"Do you train our staff to maintain the HIRARC?" },
    hirarcFaq5A: { en:"Yes. We conduct HIRARC methodology workshops for your safety committee so they can update the register as conditions change between our formal reviews.", ms:"Yes. We conduct HIRARC methodology workshops for your safety committee so they can update the register as conditions change between our formal reviews.", zh:"Yes. We conduct HIRARC methodology workshops for your safety committee so they can update the register as conditions change between our formal reviews.", ta:"Yes. We conduct HIRARC methodology workshops for your safety committee so they can update the register as conditions change between our formal reviews." },
    hirarcFaq6Q: { en:"Is HIRARC required for small offices?", ms:"Is HIRARC required for small offices?", zh:"Is HIRARC required for small offices?", ta:"Is HIRARC required for small offices?" },
    hirarcFaq6A: { en:"If you employ fewer than 5 workers, a full HIRARC is not legally required. However, we recommend a simplified hazard checklist for your own protection.", ms:"If you employ fewer than 5 workers, a full HIRARC is not legally required. However, we recommend a simplified hazard checklist for your own protection.", zh:"If you employ fewer than 5 workers, a full HIRARC is not legally required. However, we recommend a simplified hazard checklist for your own protection.", ta:"If you employ fewer than 5 workers, a full HIRARC is not legally required. However, we recommend a simplified hazard checklist for your own protection." },
    hirarcCtaTitle: { en:"Get Your HIRARC Right Before DOSH Asks for It", ms:"Get Your HIRARC Right Before DOSH Asks for It", zh:"Get Your HIRARC Right Before DOSH Asks for It", ta:"Get Your HIRARC Right Before DOSH Asks for It" },
    hirarcCtaSubtitle: { en:"Site-specific hazard identification, quantified risk scoring, and implementation support that keeps your register current and your facility protected.", ms:"Site-specific hazard identification, quantified risk scoring, and implementation support that keeps your register current and your facility protected.", zh:"Site-specific hazard identification, quantified risk scoring, and implementation support that keeps your register current and your facility protected.", ta:"Site-specific hazard identification, quantified risk scoring, and implementation support that keeps your register current and your facility protected." },
