    oshCoordHeroTitle: { en:"OSH Coordinator (OSH-C) Appointment — Section 29A OSH Act 2022", ms:"OSH Coordinator (OSH-C) Appointment — Section 29A OSH Act 2022", zh:"OSH Coordinator (OSH-C) Appointment — Section 29A OSH Act 2022", ta:"OSH Coordinator (OSH-C) Appointment — Section 29A OSH Act 2022" },
    oshCoordHeroSubtitle: { en:"Mandatory for every employer with 5 or more workers. Non-compliance exposes directors to criminal liability under Section 29A of the OSH (Amendment) Act 2022.", ms:"Mandatory for every employer with 5 or more workers. Non-compliance exposes directors to criminal liability under Section 29A of the OSH (Amendment) Act 2022.", zh:"Mandatory for every employer with 5 or more workers. Non-compliance exposes directors to criminal liability under Section 29A of the OSH (Amendment) Act 2022.", ta:"Mandatory for every employer with 5 or more workers. Non-compliance exposes directors to criminal liability under Section 29A of the OSH (Amendment) Act 2022." },
