    oshCoordProblemTitle: { en:"Do You Need an OSH Coordinator?", ms:"Do You Need an OSH Coordinator?", zh:"Do You Need an OSH Coordinator?", ta:"Do You Need an OSH Coordinator?" },
    oshCoordProblemText: { en:"Since 2022, Malaysian employers must appoint a certified OSH Coordinator if they employ 5 or more people. The coordinator must possess competency certificates recognised by DOSH. Many SMEs appoint an internal staff member without proper training, exposing the company and its directors to prosecution.", ms:"Since 2022, Malaysian employers must appoint a certified OSH Coordinator if they employ 5 or more people. The coordinator must possess competency certificates recognised by DOSH. Many SMEs appoint an internal staff member without proper training, exposing the company and its directors to prosecution.", zh:"Since 2022, Malaysian employers must appoint a certified OSH Coordinator if they employ 5 or more people. The coordinator must possess competency certificates recognised by DOSH. Many SMEs appoint an internal staff member without proper training, exposing the company and its directors to prosecution.", ta:"Since 2022, Malaysian employers must appoint a certified OSH Coordinator if they employ 5 or more people. The coordinator must possess competency certificates recognised by DOSH. Many SMEs appoint an internal staff member without proper training, exposing the company and its directors to prosecution." },
    oshCoordStakesTitle: { en:"The Stakes", ms:"The Stakes", zh:"The Stakes", ta:"The Stakes" },
    oshCoordStakesH1: { en:"Criminal Liability", ms:"Criminal Liability", zh:"Criminal Liability", ta:"Criminal Liability" },
    oshCoordStakesP1: { en:"Failure to appoint a certified OSH Coordinator is a criminal offence. Directors and employers can face corporate fines up to RM500,000 under Section 29A of the OSH (Amendment) Act 2022.", ms:"Failure to appoint a certified OSH Coordinator is a criminal offence. Directors and employers can face corporate fines up to RM500,000 under Section 29A of the OSH (Amendment) Act 2022.", zh:"Failure to appoint a certified OSH Coordinator is a criminal offence. Directors and employers can face corporate fines up to RM500,000 under Section 29A of the OSH (Amendment) Act 2022.", ta:"Failure to appoint a certified OSH Coordinator is a criminal offence. Directors and employers can face corporate fines up to RM500,000 under Section 29A of the OSH (Amendment) Act 2022." },
