    auditProblemTitle: { en:"Do You Need a Safety Audit?", ms:"Do You Need a Safety Audit?", zh:"Do You Need a Safety Audit?", ta:"Do You Need a Safety Audit?" },
    auditProblemText: { en:"DOSH inspections can be announced or unannounced. When they arrive, employers have hours — not weeks — to produce machinery registers, HIRARC documents, training records, and incident investigation files. Facilities that scramble to prepare during the inspection rarely pass cleanly.", ms:"DOSH inspections can be announced or unannounced. When they arrive, employers have hours — not weeks — to produce machinery registers, HIRARC documents, training records, and incident investigation files. Facilities that scramble to prepare during the inspection rarely pass cleanly.", zh:"DOSH inspections can be announced or unannounced. When they arrive, employers have hours — not weeks — to produce machinery registers, HIRARC documents, training records, and incident investigation files. Facilities that scramble to prepare during the inspection rarely pass cleanly.", ta:"DOSH inspections can be announced or unannounced. When they arrive, employers have hours — not weeks — to produce machinery registers, HIRARC documents, training records, and incident investigation files. Facilities that scramble to prepare during the inspection rarely pass cleanly." },
    auditStakesTitle: { en:"The Stakes", ms:"The Stakes", zh:"The Stakes", ta:"The Stakes" },
    auditStakesH1: { en:"Stop-Work Orders", ms:"Stop-Work Orders", zh:"Stop-Work Orders", ta:"Stop-Work Orders" },
    auditStakesP1: { en:"A failed DOSH audit results in fines, improvement notices, and potentially stop-work orders that halt production. Each day of stopped production costs thousands.", ms:"A failed DOSH audit results in fines, improvement notices, and potentially stop-work orders that halt production. Each day of stopped production costs thousands.", zh:"A failed DOSH audit results in fines, improvement notices, and potentially stop-work orders that halt production. Each day of stopped production costs thousands.", ta:"A failed DOSH audit results in fines, improvement notices, and potentially stop-work orders that halt production. Each day of stopped production costs thousands." },
    auditStakesH2: { en:"Criminal Prosecution", ms:"Criminal Prosecution", zh:"Criminal Prosecution", ta:"Criminal Prosecution" },
    auditStakesP2: { en:"Repeat failures can lead to prosecution under the OSH Act. Directors face personal liability when systematic safety failures are identified.", ms:"Repeat failures can lead to prosecution under the OSH Act. Directors face personal liability when systematic safety failures are identified.", zh:"Repeat failures can lead to prosecution under the OSH Act. Directors face personal liability when systematic safety failures are identified.", ta:"Repeat failures can lead to prosecution under the OSH Act. Directors face personal liability when systematic safety failures are identified." },
