    auditFaq1Q: { en:"How long does a safety audit take?", ms:"How long does a safety audit take?", zh:"How long does a safety audit take?", ta:"How long does a safety audit take?" },
    auditFaq1A: { en:"A typical SME facility requires 1 day on site. Large industrial complexes with multiple buildings may require 2–3 days. The report is delivered within 5–7 working days.", ms:"A typical SME facility requires 1 day on site. Large industrial complexes with multiple buildings may require 2–3 days. The report is delivered within 5–7 working days.", zh:"A typical SME facility requires 1 day on site. Large industrial complexes with multiple buildings may require 2–3 days. The report is delivered within 5–7 working days.", ta:"A typical SME facility requires 1 day on site. Large industrial complexes with multiple buildings may require 2–3 days. The report is delivered within 5–7 working days." },
