    auditFaq2A: { en:"We audit against the OSH (Amendment) Act 2022, USECHH Regulations 2000, Occupational Safety and Health (Noise Exposure) Regulations 2019, and relevant DOSH industry codes of practice.", ms:"We audit against the OSH (Amendment) Act 2022, USECHH Regulations 2000, Occupational Safety and Health (Noise Exposure) Regulations 2019, and relevant DOSH industry codes of practice.", zh:"We audit against the OSH (Amendment) Act 2022, USECHH Regulations 2000, Occupational Safety and Health (Noise Exposure) Regulations 2019, and relevant DOSH industry codes of practice.", ta:"We audit against the OSH (Amendment) Act 2022, USECHH Regulations 2000, Occupational Safety and Health (Noise Exposure) Regulations 2019, and relevant DOSH industry codes of practice." },
    auditFaq3Q: { en:"Will you share the audit report with DOSH?", ms:"Will you share the audit report with DOSH?", zh:"Will you share the audit report with DOSH?", ta:"Will you share the audit report with DOSH?" },
    auditFaq3A: { en:"No. The audit report is confidential to you. We prepare it in a format that YOU can present to DOSH if you choose, but we do not submit it on your behalf.", ms:"No. The audit report is confidential to you. We prepare it in a format that YOU can present to DOSH if you choose, but we do not submit it on your behalf.", zh:"No. The audit report is confidential to you. We prepare it in a format that YOU can present to DOSH if you choose, but we do not submit it on your behalf.", ta:"No. The audit report is confidential to you. We prepare it in a format that YOU can present to DOSH if you choose, but we do not submit it on your behalf." },
    auditFaq4Q: { en:"Can you accompany us during a DOSH inspection?", ms:"Can you accompany us during a DOSH inspection?", zh:"Can you accompany us during a DOSH inspection?", ta:"Can you accompany us during a DOSH inspection?" },
    auditFaq4A: { en:"Yes. We provide on-site advisory during DOSH inspections to help answer technical questions and present documentation in the format inspectors expect.", ms:"Yes. We provide on-site advisory during DOSH inspections to help answer technical questions and present documentation in the format inspectors expect.", zh:"Yes. We provide on-site advisory during DOSH inspections to help answer technical questions and present documentation in the format inspectors expect.", ta:"Yes. We provide on-site advisory during DOSH inspections to help answer technical questions and present documentation in the format inspectors expect." },
    auditFaq5Q: { en:"What if we fail the audit?", ms:"What if we fail the audit?", zh:"What if we fail the audit?", ta:"What if we fail the audit?" },
    auditFaq5A: { en:"There is no \"pass\" or \"fail\" in an internal audit — only gaps identified and prioritised. Our goal is to find and close gaps BEFORE DOSH does. We provide a remediation timeline for every finding.", ms:"There is no \"pass\" or \"fail\" in an internal audit — only gaps identified and prioritised. Our goal is to find and close gaps BEFORE DOSH does. We provide a remediation timeline for every finding.", zh:"There is no \"pass\" or \"fail\" in an internal audit — only gaps identified and prioritised. Our goal is to find and close gaps BEFORE DOSH does. We provide a remediation timeline for every finding.", ta:"There is no \"pass\" or \"fail\" in an internal audit — only gaps identified and prioritised. Our goal is to find and close gaps BEFORE DOSH does. We provide a remediation timeline for every finding." },
    auditFaq6Q: { en:"Is audit support HRD Corp claimable?", ms:"Is audit support HRD Corp claimable?", zh:"Is audit support HRD Corp claimable?", ta:"Is audit support HRD Corp claimable?" },
    auditFaq6A: { en:"Safety audit and inspection training is HRD Corp claimable when structured as a formal competency programme. We can advise on claim eligibility for your specific audit scope.", ms:"Safety audit and inspection training is HRD Corp claimable when structured as a formal competency programme. We can advise on claim eligibility for your specific audit scope.", zh:"Safety audit and inspection training is HRD Corp claimable when structured as a formal competency programme. We can advise on claim eligibility for your specific audit scope.", ta:"Safety audit and inspection training is HRD Corp claimable when structured as a formal competency programme. We can advise on claim eligibility for your specific audit scope." },
