    wahProblemTitle: { en:"Do You Need WAH Training?", ms:"Do You Need WAH Training?", zh:"Do You Need WAH Training?", ta:"Do You Need WAH Training?" },
    wahProblemText: { en:"Falls from height remain the leading cause of death and serious injury on Malaysian construction sites. The CIDB and DOSH require specific WAH competency for workers operating above 2 metres. Many sites rely on generic inductions that do not address the actual fall hazards of the specific structure being built.", ms:"Falls from height remain the leading cause of death and serious injury on Malaysian construction sites. The CIDB and DOSH require specific WAH competency for workers operating above 2 metres. Many sites rely on generic inductions that do not address the actual fall hazards of the specific structure being built.", zh:"Falls from height remain the leading cause of death and serious injury on Malaysian construction sites. The CIDB and DOSH require specific WAH competency for workers operating above 2 metres. Many sites rely on generic inductions that do not address the actual fall hazards of the specific structure being built.", ta:"Falls from height remain the leading cause of death and serious injury on Malaysian construction sites. The CIDB and DOSH require specific WAH competency for workers operating above 2 metres. Many sites rely on generic inductions that do not address the actual fall hazards of the specific structure being built." },
    wahStakesTitle: { en:"The Stakes", ms:"The Stakes", zh:"The Stakes", ta:"The Stakes" },
    wahStakesH1: { en:"Fatality &amp; Prosecution Risk", ms:"Fatality &amp; Prosecution Risk", zh:"Fatality &amp; Prosecution Risk", ta:"Fatality &amp; Prosecution Risk" },
    wahStakesP1: { en:"A single fatal fall triggers immediate CIDB and DOSH investigations, potential project suspension, criminal charges under the Factories and Machinery Act, and massive insurance premium increases.", ms:"A single fatal fall triggers immediate CIDB and DOSH investigations, potential project suspension, criminal charges under the Factories and Machinery Act, and massive insurance premium increases.", zh:"A single fatal fall triggers immediate CIDB and DOSH investigations, potential project suspension, criminal charges under the Factories and Machinery Act, and massive insurance premium increases.", ta:"A single fatal fall triggers immediate CIDB and DOSH investigations, potential project suspension, criminal charges under the Factories and Machinery Act, and massive insurance premium increases." },
    wahStakesH2: { en:"Permanent Disability", ms:"Permanent Disability", zh:"Permanent Disability", ta:"Permanent Disability" },
    wahStakesP2: { en:"Survivors of falls from height often face permanent disability. The human and financial cost to workers and their families is devastating and entirely preventable with proper training and equipment.", ms:"Survivors of falls from height often face permanent disability. The human and financial cost to workers and their families is devastating and entirely preventable with proper training and equipment.", zh:"Survivors of falls from height often face permanent disability. The human and financial cost to workers and their families is devastating and entirely preventable with proper training and equipment.", ta:"Survivors of falls from height often face permanent disability. The human and financial cost to workers and their families is devastating and entirely preventable with proper training and equipment." },
    wahStakesH3: { en:"Suspension Trauma", ms:"Suspension Trauma", zh:"Suspension Trauma", ta:"Suspension Trauma" },
    wahStakesP3: { en:"A worker caught by their harness can suffer suspension trauma within 15 minutes. Without a rescue plan, a survivable fall becomes a fatal event. Every WAH programme must include rescue planning.", ms:"A worker caught by their harness can suffer suspension trauma within 15 minutes. Without a rescue plan, a survivable fall becomes a fatal event. Every WAH programme must include rescue planning.", zh:"A worker caught by their harness can suffer suspension trauma within 15 minutes. Without a rescue plan, a survivable fall becomes a fatal event. Every WAH programme must include rescue planning.", ta:"A worker caught by their harness can suffer suspension trauma within 15 minutes. Without a rescue plan, a survivable fall becomes a fatal event. Every WAH programme must include rescue planning." },
