    wahFaq1Q: { en:"How long does WAH training take?", ms:"How long does WAH training take?", zh:"How long does WAH training take?", ta:"How long does WAH training take?" },
    wahFaq1A: { en:"The standard programme is 2 days — Day 1 theory, Day 2 hands-on practical with harnesses, anchors, and MEWP operation. On-site delivery minimises downtime.", ms:"The standard programme is 2 days — Day 1 theory, Day 2 hands-on practical with harnesses, anchors, and MEWP operation. On-site delivery minimises downtime.", zh:"The standard programme is 2 days — Day 1 theory, Day 2 hands-on practical with harnesses, anchors, and MEWP operation. On-site delivery minimises downtime.", ta:"The standard programme is 2 days — Day 1 theory, Day 2 hands-on practical with harnesses, anchors, and MEWP operation. On-site delivery minimises downtime." },
    wahFaq2Q: { en:"Do workers need a medical check before WAH training?", ms:"Do workers need a medical check before WAH training?", zh:"Do workers need a medical check before WAH training?", ta:"Do workers need a medical check before WAH training?" },
    wahFaq2A: { en:"While not mandatory for training, workers with heart conditions, epilepsy, or severe vertigo should not perform WAH duties. We recommend a basic fitness assessment.", ms:"While not mandatory for training, workers with heart conditions, epilepsy, or severe vertigo should not perform WAH duties. We recommend a basic fitness assessment.", zh:"While not mandatory for training, workers with heart conditions, epilepsy, or severe vertigo should not perform WAH duties. We recommend a basic fitness assessment.", ta:"While not mandatory for training, workers with heart conditions, epilepsy, or severe vertigo should not perform WAH duties. We recommend a basic fitness assessment." },
    wahFaq3Q: { en:"Can you train on our active construction site?", ms:"Can you train on our active construction site?", zh:"Can you train on our active construction site?", ta:"Can you train on our active construction site?" },
    wahFaq3A: { en:"Yes. We prefer on-site delivery using your actual structures, anchors, and equipment. This makes the training immediately applicable and more memorable.", ms:"Yes. We prefer on-site delivery using your actual structures, anchors, and equipment. This makes the training immediately applicable and more memorable.", zh:"Yes. We prefer on-site delivery using your actual structures, anchors, and equipment. This makes the training immediately applicable and more memorable.", ta:"Yes. We prefer on-site delivery using your actual structures, anchors, and equipment. This makes the training immediately applicable and more memorable." },
    wahFaq4Q: { en:"What happens if a worker fails the practical assessment?", ms:"What happens if a worker fails the practical assessment?", zh:"What happens if a worker fails the practical assessment?", ta:"What happens if a worker fails the practical assessment?" },
    wahFaq4A: { en:"We provide additional supervised practice and re-assessment at no extra charge. Workers who cannot safely perform the required tasks will not be certified.", ms:"We provide additional supervised practice and re-assessment at no extra charge. Workers who cannot safely perform the required tasks will not be certified.", zh:"We provide additional supervised practice and re-assessment at no extra charge. Workers who cannot safely perform the required tasks will not be certified.", ta:"We provide additional supervised practice and re-assessment at no extra charge. Workers who cannot safely perform the required tasks will not be certified." },
    wahFaq5Q: { en:"Is WAH training HRD Corp claimable?", ms:"Is WAH training HRD Corp claimable?", zh:"Is WAH training HRD Corp claimable?", ta:"Is WAH training HRD Corp claimable?" },
    wahFaq5A: { en:"Yes. James Issachar (Trainer ID: 62976) is HRD Corp-certified. We assist with e-TRiS grant applications for batch training.", ms:"Yes. James Issachar (Trainer ID: 62976) is HRD Corp-certified. We assist with e-TRiS grant applications for batch training.", zh:"Yes. James Issachar (Trainer ID: 62976) is HRD Corp-certified. We assist with e-TRiS grant applications for batch training.", ta:"Yes. James Issachar (Trainer ID: 62976) is HRD Corp-certified. We assist with e-TRiS grant applications for batch training." },
    wahFaq6Q: { en:"What is suspension trauma?", ms:"What is suspension trauma?", zh:"What is suspension trauma?", ta:"What is suspension trauma?" },
    wahFaq6A: { en:"When a worker falls and is caught by their harness, blood pools in the legs. Without rescue within 15 minutes, the worker can lose consciousness or suffer kidney damage. Every WAH programme includes rescue planning.", ms:"When a worker falls and is caught by their harness, blood pools in the legs. Without rescue within 15 minutes, the worker can lose consciousness or suffer kidney damage. Every WAH programme includes rescue planning.", zh:"When a worker falls and is caught by their harness, blood pools in the legs. Without rescue within 15 minutes, the worker can lose consciousness or suffer kidney damage. Every WAH programme includes rescue planning.", ta:"When a worker falls and is caught by their harness, blood pools in the legs. Without rescue within 15 minutes, the worker can lose consciousness or suffer kidney damage. Every WAH programme includes rescue planning." },
